import streamlit as st
import streamlit.components.v1 as components
HTML = '<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>\n*{box-sizing:border-box}body{margin:0;background:#f0f9ff;color:#193b52;font:15px system-ui}main{max-width:650px;margin:auto;padding:14px 12px 35px}button,input,select{font:inherit;padding:12px;border:1px solid #c9e1ed;border-radius:13px;background:white;color:#234c63}button{cursor:pointer;touch-action:manipulation}button:disabled{opacity:.45;cursor:default}h1{font-size:24px;margin:4px 0}h2{font-size:19px}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:13px}.coin{background:#fff0b4;border-radius:15px;padding:11px;font-weight:bold}.room{height:360px;position:relative;overflow:hidden;border:9px solid white;border-radius:26px;background:repeating-linear-gradient(90deg,#daf4fc 0 55px,#cfedf7 55px 57px);box-shadow:0 8px 25px #3886a31c;touch-action:none}.floor{position:absolute;inset:64% 0 0;background:repeating-linear-gradient(0deg,#f6e9d1 0 30px,#ead7b9 30px 32px)}.window{position:absolute;left:25px;top:22px;width:92px;height:85px;background:#8dd5f2;border:8px solid white;border-radius:16px;box-shadow:inset 0 0 0 2px #d7f3ff}.window:after{content:\'☁️\';font-size:40px}.penguin{position:absolute;left:calc(50% - 45px);top:138px;width:90px;height:125px;background:#274c68;border-radius:48% 48% 43% 43%;z-index:4;animation:breathe 3s ease-in-out infinite;pointer-events:none}.belly{position:absolute;left:13px;top:30px;width:64px;height:83px;border-radius:50%;background:#fffdfa}.eyes{position:absolute;left:22px;top:32px;letter-spacing:17px;font-size:19px;color:#15354b;white-space:nowrap}.beak{position:absolute;left:35px;top:59px;width:21px;height:13px;border-radius:50%;background:#ffbb50}.feet{position:absolute;bottom:-5px;left:10px;width:28px;height:14px;border-radius:50%;background:#ffbb50;box-shadow:42px 0 #ffbb50}.wing{position:absolute;left:-11px;top:53px;width:20px;height:48px;background:#274c68;border-radius:60%;transform:rotate(20deg)}.hat{position:absolute;top:-28px;left:17px;font-size:48px;z-index:5}.item{position:absolute;font-size:51px;line-height:1;cursor:grab;z-index:6;user-select:none;touch-action:none;filter:drop-shadow(0 5px 2px #38557022)}.item.selected{outline:2px dashed #3776bf;border-radius:8px}.tabs{display:flex;gap:6px;margin:18px 0}.tabs button{flex:1;padding:12px 4px;font-weight:bold}.active{background:#386ecb;color:white;border-color:#386ecb}.card{background:white;border:1px solid #d8e9f2;border-radius:18px;padding:16px;margin:10px 0}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.row>*{min-width:0}small{color:#536e7e}input,select{width:100%;margin:7px 0 12px}label{display:block}.primary{background:#386ecb;color:white;border:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.shopicon{font-size:38px}p{line-height:1.65}.splash{position:fixed;inset:0;background:#a8e4f5;z-index:100;display:grid;place-content:center;text-align:center}.splash .icon{background:#386ecb;padding:20px;border-radius:28px;font-size:65px;margin:auto}.toast{background:#fff1b5;padding:12px;border-radius:12px;display:none;margin:10px 0}.subtitle{font-size:12px;color:#526f80}.hint{text-align:center;font-size:12px;margin:10px;color:#486a7f}@keyframes breathe{50%{transform:translateY(-5px) rotate(2deg)}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}\nbody{padding-bottom:85px}main{padding:12px 12px 30px}.room{height:300px;border-width:6px;touch-action:pan-y}.penguin{top:110px}.tabs{position:fixed;bottom:0;left:0;right:0;margin:0;background:white;z-index:50;padding:10px 8px max(10px,env(safe-area-inset-bottom));box-shadow:0 -3px 18px #255c7615}.tabs button{font-size:13px;min-height:52px;border:0;padding:10px 3px}.card{padding:14px}.grid{gap:8px}button{min-height:48px}input,select{font-size:16px;min-height:48px}summary{min-height:48px;padding:14px 0;cursor:pointer}.item{cursor:pointer}.window{height:65px;width:80px}.row{gap:12px}header h1{font-size:22px}#movebar{background:#e5f2ff;border-radius:15px;padding:10px;text-align:center;margin:10px 0}#movebar button{min-width:48px;padding:8px;margin:2px}.penguin{width:156px;height:156px;left:calc(50% - 78px);top:105px;background:transparent;border-radius:0}.mascot{width:100%;height:100%;object-fit:contain;border-radius:35%;mix-blend-mode:multiply}.hat{left:51px;top:-10px;font-size:48px}.room{background:#daf4fc}.coin{background:#ffe680;color:#604817}.primary,.tabs .active{background:#4b65db}</style><div class="splash" id="splash"><div class="icon">🐧</div><h1>냉장고 펭귄</h1><p>남김없이 쓰고, 귀엽게 꾸며요.</p></div><main><header><div><h1>냉장고 펭귄 🐧</h1></div><div class="coin" id="coins"></div></header><div class="room" id="room"><div class="floor"></div><div class="window"></div><div class="penguin"><img class="mascot" alt="통통한 냉장고 펭귄" src="data:image/jpeg;base64,"><div class="hat" id="hat"></div></div><div id="furniture"></div></div><div class="toast" id="toast" role="status"></div><div class="tabs"><button onclick="tab=\'fridge\';render()" id="tfridge">🥕 냉장고</button><button onclick="tab=\'shop\';render()" id="tshop">🛍 상점</button><button onclick="tab=\'closet\';render()" id="tcloset">🪑 꾸미기</button><button onclick="tab=\'save\';render()" id="tsave">⚙ 저장</button></div><div id="movebar" hidden></div><section id="panel"></section></main><script>\nconst catalog=[{id:\'plant\',name:\'작은 화분\',icon:\'🪴\',cost:0,type:\'furniture\'},{id:\'chair\',name:\'폭신 의자\',icon:\'🪑\',cost:25,type:\'furniture\'},{id:\'bed\',name:\'낮잠 침대\',icon:\'🛏️\',cost:45,type:\'furniture\'},{id:\'lamp\',name:\'노란 조명\',icon:\'💡\',cost:20,type:\'furniture\'},{id:\'bear\',name:\'곰 인형\',icon:\'🧸\',cost:30,type:\'furniture\'},{id:\'flower\',name:\'꽃 한 다발\',icon:\'🌷\',cost:20,type:\'furniture\'},{id:\'crown\',name:\'왕관\',icon:\'👑\',cost:35,type:\'hat\'},{id:\'ribbon\',name:\'리본\',icon:\'🎀\',cost:20,type:\'hat\'},{id:\'cap\',name:\'산책 모자\',icon:\'👒\',cost:30,type:\'hat\'},{id:\'peach\',name:\'복숭아 벽지\',icon:\'🍑\',cost:30,type:\'wall\'},{id:\'mint\',name:\'민트 벽지\',icon:\'🌿\',cost:30,type:\'wall\'}];\nconst defaults=()=>({version:1,coins:30,owned:[\'plant\'],placed:[{id:\'plant\',x:15,y:72}],hat:\'\',wall:\'\',foods:[],rewardDate:\'\',rewardCount:0});let state=defaults(),tab=\'fridge\';const esc=s=>String(s||\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,\'0\')}-${String(d.getDate()).padStart(2,\'0\')}`};function valid(s){if(!s||s.version!==1||!Number.isInteger(s.coins)||s.coins<0||s.coins>1000000||!Array.isArray(s.foods)||s.foods.length>200||!Array.isArray(s.owned)||s.owned.some(id=>!catalog.some(c=>c.id===id))||!Array.isArray(s.placed)||s.placed.length>catalog.length||!Number.isInteger(s.rewardCount)||s.rewardCount<0||s.rewardCount>3||typeof s.rewardDate!==\'string\'||s.rewardDate.length>10)throw Error();if(![\'\',\'crown\',\'ribbon\',\'cap\'].includes(s.hat)||![\'\',\'peach\',\'mint\'].includes(s.wall)||(s.hat&&!s.owned.includes(s.hat))||(s.wall&&!s.owned.includes(s.wall)))throw Error();let ids=new Set();for(let f of s.foods){if(typeof f.id!==\'string\'||!/^[a-z0-9-]+$/i.test(f.id)||ids.has(f.id)||typeof f.name!==\'string\'||!f.name.trim()||f.name.length>50||!Number.isFinite(f.qty)||f.qty<=0||f.qty>9999||![\'개\',\'g\',\'ml\',\'봉\',\'팩\'].includes(f.unit)||typeof f.due!==\'string\'||(f.due&&!/^\\d{4}-\\d{2}-\\d{2}$/.test(f.due)))throw Error();ids.add(f.id)}ids=new Set();for(let p of s.placed){if(!s.owned.includes(p.id)||!catalog.some(c=>c.id===p.id&&c.type===\'furniture\')||ids.has(p.id)||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>84||p.y<0||p.y>80)throw Error();ids.add(p.id)}return s}\ntry{const stored=localStorage.getItem(\'fridge-penguin-v1\');if(stored)state=valid(JSON.parse(stored))}catch{setTimeout(()=>notify(\'저장 기록을 읽지 못했어요. 백업 파일이 있다면 불러와 주세요.\'),3100)}function save(){try{localStorage.setItem(\'fridge-penguin-v1\',JSON.stringify(state))}catch{notify(\'브라우저 저장이 안 돼요. 저장 탭에서 백업하세요.\')}}let timer;function notify(t){let el=document.getElementById(\'toast\');el.textContent=t;el.style.display=\'block\';clearTimeout(timer);timer=setTimeout(()=>el.style.display=\'none\',6500)}function dayReset(){if(state.rewardDate!==today()){state.rewardDate=today();state.rewardCount=0}}\nfunction drawRoom(){document.getElementById(\'coins\').textContent=\'🪙 \'+state.coins;document.getElementById(\'hat\').textContent=catalog.find(c=>c.id===state.hat)?.icon||\'\';let room=document.getElementById(\'room\');room.style.background=state.wall===\'peach\'?\'#ffe3d6\':state.wall===\'mint\'?\'#d9f2de\':\'\';document.getElementById(\'furniture\').innerHTML=state.placed.map(p=>`<div class="item" data-item="${p.id}" style="left:${p.x}%;top:${p.y}%" role="button" tabindex="0" aria-label="${esc(catalog.find(c=>c.id===p.id).name)}. 드래그하거나 선택 후 방향키로 이동">${catalog.find(c=>c.id===p.id).icon}</div>`).join(\'\');document.querySelectorAll(\'.item\').forEach(el=>{el.onclick=()=>selectFurniture(el.dataset.item);el.onkeydown=e=>{if(e.key===\'Enter\'||e.key===\' \'){e.preventDefault();selectFurniture(el.dataset.item)}}})}\nlet selectedFurniture=\'\';\nfunction selectFurniture(id){selectedFurniture=id;document.querySelectorAll(\'.item\').forEach(el=>el.classList.toggle(\'selected\',el.dataset.item===id));let bar=document.getElementById(\'movebar\');bar.hidden=false;bar.innerHTML=\'<b>\'+catalog.find(c=>c.id===id).name+\'</b><br><button onclick="moveFurniture(-7,0)" aria-label="왼쪽">◀</button><button onclick="moveFurniture(0,-7)" aria-label="위">▲</button><button onclick="moveFurniture(0,7)" aria-label="아래">▼</button><button onclick="moveFurniture(7,0)" aria-label="오른쪽">▶</button><button onclick="finishMoving()">완료</button>\'}\nfunction finishMoving(){selectedFurniture=\'\';document.getElementById(\'movebar\').hidden=true;document.querySelectorAll(\'.item\').forEach(el=>el.classList.remove(\'selected\'))}\nfunction moveFurniture(dx,dy){let p=state.placed.find(p=>p.id===selectedFurniture);if(!p)return;p.x=Math.max(0,Math.min(84,p.x+dx));p.y=Math.max(0,Math.min(80,p.y+dy));save();drawRoom();selectFurniture(p.id)}\n\nfunction render(){finishMoving();dayReset();drawRoom();[\'fridge\',\'shop\',\'closet\',\'save\'].forEach(t=>document.getElementById(\'t\'+t).className=tab===t?\'active\':\'\');let panel=document.getElementById(\'panel\');if(tab===\'fridge\'){panel.innerHTML=`<div class="card"><b>오늘의 재료 활용 보상 ${state.rewardCount}/3</b><details><summary>＋ 재료 넣기</summary><form id="add"><label>재료 이름<input name="name" maxlength="50" required placeholder="예: 당근"></label><div class="row"><label style="flex:1">수량<input name="qty" type="number" min="0.01" max="9999" step="0.01" required value="1"></label><label style="flex:1">단위<select name="unit"><option>개</option><option>g</option><option>ml</option><option>봉</option><option>팩</option></select></label></div><label>먼저 확인할 날짜 · 선택<input type="date" name="due"></label><button class="primary">등록하기</button></form></details></div><div id="foods"></div><small>날짜만으로 식품 안전을 판단하지 마세요.</small>`;document.getElementById(\'add\').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),name=f.get(\'name\').trim(),qty=Number(f.get(\'qty\'));if(!name||!Number.isFinite(qty)||qty<=0||qty>9999)return;if(state.foods.length>=200){notify(\'재료는 최대 200개예요.\');return}state.foods.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2),name,qty,unit:f.get(\'unit\'),due:f.get(\'due\')});save();render();notify(\'냉장고에 기록했어요.\')};let foods=[...state.foods].sort((a,b)=>(a.due||\'9999\').localeCompare(b.due||\'9999\'));document.getElementById(\'foods\').innerHTML=foods.length?foods.map(f=>`<div class="card"><b>🥕 ${esc(f.name)}</b><p>${f.qty} ${f.unit}${f.due?\' · 확인일 \'+esc(f.due):\'\'}</p>${f.due&&f.due<today()?\'<small>확인 날짜가 지났어요. 상태와 표시사항을 확인하세요.</small>\':\'\'}<label>이번에 실제 사용한 양<input id="qty-${f.id}" type="number" min="0.01" max="${f.qty}" step="0.01" value="${Math.min(1,f.qty)}"></label><button class="primary" onclick="useFood(\'${f.id}\')">사용했어요</button> <button onclick="removeFood(\'${f.id}\')">삭제 · 보상 없음</button></div>`).join(\'\'):\'<div class="card">아직 재료가 없어요 🥕</div>\'}\nif(tab===\'shop\'){panel.innerHTML=\'<h2>펭귄의 작은 상점</h2><div class="grid">\'+catalog.map(c=>`<div class="card"><div class="shopicon">${c.icon}</div><p>${c.name}</p><button onclick="buy(\'${c.id}\')" ${state.owned.includes(c.id)||state.coins<c.cost?\'disabled\':\'\'}>${state.owned.includes(c.id)?\'보유 중\':c.cost+\' 코인\'}</button></div>`).join(\'\')+\'</div>\'}\nif(tab===\'closet\'){panel.innerHTML=\'<h2>내 방 꾸미기</h2><button onclick="state.hat=\\\'\\\';state.wall=\\\'\\\';save();render()">기본 옷·벽지</button><div class="grid">\'+catalog.filter(c=>state.owned.includes(c.id)).map(c=>`<div class="card"><span class="shopicon">${c.icon}</span><p>${c.name}</p><button onclick="equip(\'${c.id}\')">${c.type===\'furniture\'?(state.placed.some(p=>p.id===c.id)?\'넣어 두기\':\'방에 꺼내기\'):\'적용하기\'}</button></div>`).join(\'\')+\'</div>\'}\nif(tab===\'save\'){panel.innerHTML=`<div class="card"><h2>게임 보관함</h2><small>이 기기에 저장 · 가족 공유 없음</small><button class="primary" id="export">백업 다운로드</button><label style="margin-top:18px">백업 불러오기 · 현재 게임 대체<input type="file" id="import" accept="application/json"></label><details><summary>처음부터 다시</summary><p>현재 재료와 코인·꾸미기 기록이 삭제돼요.</p><button id="reset">게임 초기화</button></details></div>`;document.getElementById(\'export\').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:\'application/json\'})),a=document.createElement(\'a\');a.href=u;a.download=\'냉장고펭귄_백업.json\';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.getElementById(\'import\').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();let s=valid(JSON.parse(await file.text()));if(confirm(\'현재 게임을 이 백업으로 바꿀까요?\')){state=s;save();render();notify(\'게임을 불러왔어요.\')}}catch{notify(\'올바른 게임 백업 파일인지 확인해 주세요.\')}};document.getElementById(\'reset\').onclick=()=>{if(confirm(\'정말 처음부터 다시 할까요?\')){state=defaults();save();render()}}}}\nfunction useFood(id){let f=state.foods.find(f=>f.id===id),qty=Number(document.getElementById(\'qty-\'+id).value);if(!f||!Number.isFinite(qty)||qty<=0||qty>f.qty){notify(\'남은 수량 안에서 사용량을 입력해 주세요.\');return}dayReset();f.qty=Math.round((f.qty-qty)*100)/100;state.foods=state.foods.filter(f=>f.qty>0);let reward=state.rewardCount<3;if(reward){state.rewardCount++;state.coins+=10}save();render();notify(reward?\'활용 기록 완료! 10코인을 받았어요 🪙\':\'활용 기록 완료! 오늘의 코인 보상은 모두 받았어요.\')}\nfunction removeFood(id){if(!confirm(\'재료를 삭제할까요? 코인은 지급되지 않아요.\'))return;state.foods=state.foods.filter(f=>f.id!==id);save();render()}\nfunction buy(id){let c=catalog.find(c=>c.id===id);if(!c||state.owned.includes(id)||state.coins<c.cost)return;state.coins-=c.cost;state.owned.push(id);save();render();notify(c.name+\' 구매 완료! 꾸미기 탭에서 꺼내 보세요.\')}\nfunction equip(id){let c=catalog.find(c=>c.id===id);if(!c||!state.owned.includes(id))return;if(c.type===\'hat\')state.hat=id;else if(c.type===\'wall\')state.wall=id;else if(state.placed.some(p=>p.id===id))state.placed=state.placed.filter(p=>p.id!==id);else state.placed.push({id,x:65,y:70});save();render()}\nsetTimeout(()=>document.getElementById(\'splash\').remove(),3000);render();\n</script></html>'
st.set_page_config(page_title='냉장고 펭귄',page_icon='🐧',layout='centered',initial_sidebar_state='collapsed')
st.markdown('<style>[data-testid="stSidebar"],[data-testid="stSidebarCollapsedControl"]{display:none}.block-container{padding:0 .3rem;max-width:720px}.stApp{background:#f0f9ff}</style>',unsafe_allow_html=True)
components.html(HTML,height=1400,scrolling=True)
